import numpy as np
import struct

def check_realsense_collision(points_array, collision_threshold):
    """
    Memeriksa tabrakan berdasarkan array titik 3D dan ambang batas jarak.
    Fungsi ini akan mengabaikan nilai NaN (Not a Number) dalam perhitungan 
    jarak minimum untuk mencegah error.

    Args:
        points_array (np.array): Array NumPy berisi titik-titik koordinat (N, 3).
        collision_threshold (float): Ambang batas jarak untuk deteksi tabrakan (dalam meter).

    Returns:
        tuple: Berisi (bool, float) yaitu (status tabrakan, jarak minimum yang valid).
    """
    if points_array.size == 0:
        return False, float('inf')

    # Menghitung jarak Euclidean dari setiap titik ke titik asal (0,0,0)
    distances = np.linalg.norm(points_array, axis=1)
    
    # Hanya ambil jarak yang merupakan angka valid (bukan NaN atau tak terhingga)
    valid_distances = distances[np.isfinite(distances)]

    if valid_distances.size == 0:
        return False, float('inf')

    # Cari jarak terkecil dari semua jarak yang valid
    min_distance = np.min(valid_distances)

    # Periksa apakah jarak terkecil tersebut kurang dari ambang batas tabrakan
    is_collision = min_distance < collision_threshold

    return is_collision, min_distance

