# Mengubah list of int menjadi bytearray
data = bytearray(byte_data)

# List untuk menampung semua titik yang berhasil di-parse
points_list = []

# Iterasi melalui data berdasarkan point_step
for i in range(num_points):
    # Tentukan posisi awal dari titik saat ini di dalam byte array
    start_index = i * point_step
    
    # Ambil 12 byte pertama dari titik (cukup untuk x, y, z)
    point_bytes = data[start_index : start_index + 12]
    
    # Unpack 12 byte tersebut menjadi 3 float (x, y, z)
    # '<fff' berarti little-endian, tiga float
    try:
        x, y, z = struct.unpack('<fff', point_bytes)
        points_list.append([x, y, z])
    except struct.error:
        # Jika terjadi error saat unpack (misal, data tidak lengkap),
        # tambahkan nilai NaN sebagai penanda data tidak valid.
        points_list.append([float('nan'), float('nan'), float('nan')])

# Ubah list menjadi NumPy array
points_array = np.array(points_list, dtype=np.float32)

# Tentukan ambang batas tabrakan
collision_threshold = 0.5  # 50 cm

# Panggil fungsi
is_collision, min_distance = check_realsense_collision(points_array, collision_threshold)

# Tampilkan hasil
print("--- HASIL ANALISIS TABRAKAN ---")
print(f"Jumlah total titik data: {num_points}")
print(f"Jumlah titik valid (bukan NaN) yang ditemukan: {np.count_nonzero(np.isfinite(points_array)) // 3}")
print("-" * 30)
print(f"Ambang batas tabrakan: {collision_threshold} meter")
print(f"Tabrakan terdeteksi? -> {is_collision} Collision Detected? 💥")
if np.isfinite(min_distance):
    print(f"Jarak minimum ke objek: {min_distance:.3f} meter")
else:
    print("Tidak ada objek dengan jarak yang valid terdeteksi.")